function managementFixture(){const s=make();s.lists=[{id:'a',name:'Scene A',items:['Alpha','Apple']},{id:'h1',name:'Hidden one',items:['One']},{id:'b',name:'Scene B',items:['Beta','Banana']},{id:'h2',name:'Hidden two',items:['Two']},{id:'c',name:'Scene C',items:['Gamma','Grape']}];for(const a of s.setups){a.listOrder=s.lists.map(l=>l.id);a.listIds=['a','b','c'];}C.setDrawCount(s.setups[0],'a',2);return s;}
const displayedLists=app=>[...app.d.querySelectorAll('#list-rows .list-row')].map(n=>n.dataset.listId);
function key(app,id,key){app.get(id).dispatchEvent(new app.w.KeyboardEvent('keydown',{key,bubbles:true,cancelable:true}));}
function pointer(app,target,type,x,y,id=1){const event=new app.w.Event(type,{bubbles:true,cancelable:true});Object.assign(event,{pointerId:id,button:0,isPrimary:true,clientX:x,clientY:y});target.dispatchEvent(event);return event;}
function mockRows(app){app.get('list-rows').getBoundingClientRect=()=>({left:0,right:320,top:100,bottom:400,width:320,height:300});[...app.d.querySelectorAll('#list-rows .list-row')].forEach((row,i)=>row.getBoundingClientRect=()=>({left:0,right:320,top:100+i*50,bottom:150+i*50,width:320,height:50}));}
test('All and Selected are display-only filters and compact rows keep editing and counts accessible',()=>{
 const app=ui(managementFixture());try{app.get('generate').click();app.get('lock-a').click();const before=app.saved();assert.equal(app.get('list-view-all').textContent,'All (5)');assert.equal(app.get('list-view-selected').textContent,'Selected (3)');app.get('list-view-selected').click();assert.deepEqual(displayedLists(app),['a','b','c']);assert.deepEqual(app.saved(),{...before,setups:before.setups.map((setup,i)=>i===0?{...setup,listView:'selected'}:setup)});assert.equal(app.get('list-view-selected').getAttribute('aria-pressed'),'true');assert.equal(app.d.querySelectorAll('.list-preview').length,0);assert.equal(app.get('draw-a').value,'2');assert.equal(app.get('lock-a').getAttribute('aria-pressed'),'true');app.d.querySelector('[aria-label="Edit Scene A"]').click();assert.equal(app.get('list-items').value,'Alpha\nApple');app.get('list-cancel').click();app.get('list-view-all').click();assert.deepEqual(displayedLists(app),['a','h1','b','h2','c']);assert.deepEqual(app.saved(),before);}finally{app.dom.window.close();}
});
