test('pointer dragging reorders selected rows on release and preserves hidden slots and locked results',()=>{
 const app=ui(managementFixture());try{app.get('generate').click();app.get('lock-a:1').click();app.get('list-view-selected').click();mockRows(app);const before=app.saved(),handle=app.get('drag-a');pointer(app,handle,'pointerdown',14,120);pointer(app,app.d,'pointermove',14,240);assert.equal(app.d.body.classList.contains('list-dragging'),true);assert.ok(app.d.querySelector('[data-list-id="c"]').classList.contains('drop-after'));assert.deepEqual(app.saved(),before);pointer(app,app.d,'pointerup',14,240);const saved=app.saved();assert.deepEqual(saved.setups[0].listOrder,['b','h1','c','h2','a']);assert.deepEqual(saved.setups[0].lastResult,before.setups[0].lastResult);assert.deepEqual(saved.setups[0].lockedPicks,before.setups[0].lockedPicks);assert.equal(app.d.querySelectorAll('.drop-after,.drop-before,.dragging').length,0);assert.equal(app.d.activeElement.id,'drag-a');app.get('drag-a').dispatchEvent(new app.w.MouseEvent('click',{detail:1,bubbles:true,cancelable:true}));assert.equal(app.get('move-list-dialog').open,false);}finally{app.dom.window.close();}
});
test('cancelled, outside, and unrelated pointer drags leave saved order unchanged',()=>{
 for(const cancel of ['Escape','pointercancel','outside','other-pointer']){const app=ui(managementFixture());try{app.get('list-view-selected').click();mockRows(app);const before=app.saved();pointer(app,app.get('drag-a'),'pointerdown',14,120);pointer(app,app.d,'pointermove',14,240,cancel==='other-pointer'?2:1);if(cancel==='Escape')key(app,'drag-a','Escape');else if(cancel==='pointercancel')pointer(app,app.d,'pointercancel',14,240);else if(cancel==='outside')pointer(app,app.d,'pointermove',500,240);pointer(app,app.d,'pointerup',14,240);assert.deepEqual(app.saved(),before);assert.equal(app.d.body.classList.contains('list-dragging'),false);}finally{app.dom.window.close();}}
});
test('position picker cancel and keyboard boundaries do not reorder or alter other setups',()=>{
 const app=ui(managementFixture());try{const before=app.saved();key(app,'drag-a','ArrowUp');key(app,'drag-c','ArrowDown');app.get('drag-a').click();app.change('move-list-position','c');app.get('move-list-cancel').click();assert.deepEqual(app.saved(),before);app.get('drag-a').click();app.change('move-list-position','c');app.get('move-list-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.deepEqual(app.saved().setups[0].listOrder,['h1','b','h2','c','a']);assert.deepEqual(app.saved().setups[1],before.setups[1]);}finally{app.dom.window.close();}
});
test('dragging near the list edge scrolls toward offscreen rows and cancels its animation cleanly',()=>{
 const s=managementFixture();for(let i=0;i<20;i++)s.lists.push({id:'extra-'+i,name:'Extra '+i,items:['Item']});C.syncLists(s);const app=ui(s);
 try{let nextFrame=null,cancelled=false;app.w.requestAnimationFrame=callback=>{nextFrame=callback;return 42;};app.w.cancelAnimationFrame=id=>{if(id===42){cancelled=true;nextFrame=null;}};const container=app.get('list-rows');container.getBoundingClientRect=()=>({left:0,right:320,top:100,bottom:400,width:320,height:300});[...container.querySelectorAll('.list-row')].forEach((row,i)=>row.getBoundingClientRect=()=>({left:0,right:320,top:100+i*50-container.scrollTop,bottom:150+i*50-container.scrollTop,width:320,height:50}));const before=app.saved();pointer(app,app.get('drag-a'),'pointerdown',14,120);pointer(app,app.d,'pointermove',14,395);assert.equal(typeof nextFrame,'function');nextFrame();assert.ok(container.scrollTop>0);assert.deepEqual(app.saved(),before);key(app,'drag-a','Escape');assert.equal(cancelled,true);assert.equal(nextFrame,null);assert.equal(app.d.body.classList.contains('list-dragging'),false);assert.deepEqual(app.saved(),before);}finally{app.dom.window.close();}
});

test('version-5 migration preserves saved content and initializes each setup view independently',()=>{
 const s=make(),a=s.setups[0];C.setDrawCount(a,'cars',2);const result=C.generate(s,a,()=>0);C.recordResult(s,a,result);C.toggleLock(s,a,result.picks[1]);C.toggleFavorite(s,result,a.name);C.renameFavorite(s,s.favorites[0].id,'Saved mix');s.version=5;for(const setup of s.setups)delete setup.listView;
 const before=JSON.stringify(s),m=C.parseBackup(before);assert.equal(JSON.stringify(s),before);assert.equal(m.version,13);assert.ok(m.setups.every(setup=>setup.listView==='all'));const comparable=plain(m);comparable.version=5;for(const setup of comparable.setups)delete setup.listView;assert.deepEqual(comparable,plain(s));
 const migrated=C.parseBackup(before,'selected');assert.ok(migrated.setups.every(setup=>setup.listView==='selected'));migrated.setups[0].listView='all';assert.equal(migrated.setups[1].listView,'selected');const reopened=C.parseBackup(JSON.stringify(migrated),'selected');assert.equal(reopened.setups[0].listView,'all');assert.equal(reopened.setups[1].listView,'selected');
});
