test('expanded and collapsed groups save immediately and remain independent across setups and reloads',()=>{
 const s=linkedFixture(),app=ui(s);try{
  const group=app.get('relations-vehicles');group.open=true;group.dispatchEvent(new app.w.Event('toggle'));const saved=JSON.parse(app.w.localStorage.getItem(C.STORAGE_KEY));assert.deepEqual(saved.setups[0],{...s.setups[0],expandedGroupIds:['vehicles']});assert.deepEqual(saved.setups[1],s.setups[1]);app.get('list-view-selected').click();app.d.querySelectorAll('#setup-nav button')[1].click();assert.equal(app.get('relations-vehicles').open,false);app.d.querySelectorAll('#setup-nav button')[0].click();assert.equal(app.get('relations-vehicles').open,true);
  const reloaded=ui(app.saved());try{assert.equal(reloaded.get('relations-vehicles').open,true);assert.equal(reloaded.get('list-view-selected').getAttribute('aria-pressed'),'true');reloaded.d.querySelectorAll('#setup-nav button')[1].click();assert.equal(reloaded.get('relations-vehicles').open,false);reloaded.d.querySelectorAll('#setup-nav button')[0].click();const open=reloaded.get('relations-vehicles');open.open=false;open.dispatchEvent(new reloaded.w.Event('toggle'));const collapsed=JSON.parse(reloaded.w.localStorage.getItem(C.STORAGE_KEY));assert.deepEqual(collapsed.setups[0].expandedGroupIds,[]);const reopened=ui(collapsed);try{assert.equal(reopened.get('relations-vehicles').open,false);}finally{reopened.dom.window.close();}}finally{reloaded.dom.window.close();}
 }finally{app.dom.window.close();}
});

