test('removing the last parent link restores a child at its saved position and deletion Undo regroups it',()=>{
 const s=linkedFixture();s.setups[0].listIds=[];s.setups[0].listOrder=['car_models','vehicles','suv_models'];const app=ui(s);try{
  const original=app.saved().setups[0].listOrder;app.d.querySelector('[aria-label="Edit Vehicles"]').click();app.d.querySelector('[aria-label="Remove link for Car"]').click();app.get('list-save').click();assert.deepEqual(displayedLists(app),['car_models','vehicles']);assert.deepEqual(app.saved().setups[0].listOrder,original);assert.equal(app.d.querySelector('[data-grouped-list-id="car_models"]'),null);assert.ok(app.d.querySelector('[data-grouped-list-id="suv_models"]'));
  app.d.querySelector('[aria-label="Edit Vehicles"]').click();app.get('list-delete').click();app.get('delete-list-confirm').click();assert.deepEqual(displayedLists(app),['car_models','suv_models']);app.get('undo').click();assert.deepEqual(displayedLists(app),['car_models','vehicles']);assert.deepEqual(app.saved().setups[0].listOrder,original);assert.ok(app.get('relations-vehicles').querySelector('[data-grouped-list-id="suv_models"]'));
 }finally{app.dom.window.close();}
});
