test('current schema migrates earlier saves to collapsed groups without changing existing data',()=>{
 assert.equal(C.VERSION,13);assert.deepEqual(plain(C.blankSetup().expandedGroupIds),[]);
 for(let version=1;version<=8;version++){const s=make();s.version=version;for(const setup of s.setups)delete setup.expandedGroupIds;const before=JSON.stringify(s),restored=C.parseBackup(before);assert.equal(restored.version,13);assert.ok(restored.setups.every(a=>Array.isArray(a.expandedGroupIds)&&a.expandedGroupIds.length===0));assert.equal(JSON.stringify(s),before);}
 const s=linkedFixture();s.version=8;s.lists[0].selectionMode='items';const a=s.setups[0];C.recordResult(s,a,C.generate(s,a,()=>0));C.toggleLock(s,a,a.lastResult.picks[0]);C.toggleFavorite(s,a.lastResult,a.name);for(const setup of s.setups)delete setup.expandedGroupIds;const before=JSON.stringify(s),restored=C.parseBackup(before),expected=plain(s);expected.version=13;for(const setup of expected.setups)setup.expandedGroupIds=[];assert.deepEqual(plain(restored),expected);assert.equal(JSON.stringify(s),before);
});
test('expanded groups validate parent references and reject malformed backups without mutation',()=>{
 for(const value of [undefined,null,true,{},'vehicles',['missing'],['car_models'],['vehicles','vehicles'],Array(1001).fill('vehicles')]){const s=linkedFixture();s.setups[0].expandedGroupIds=value;const before=JSON.stringify(s);assert.throws(()=>C.parseBackup(before));assert.equal(JSON.stringify(s),before);}
 const s=linkedFixture();s.setups[0].listIds=[];s.setups[0].expandedGroupIds=['vehicles'];assert.deepEqual(plain(C.parseBackup(JSON.stringify(s)).setups[0].expandedGroupIds),['vehicles']);assert.deepEqual(s.setups[1].expandedGroupIds,[]);
});
test('backup merge remaps expanded parents separately for each imported setup',()=>{
 const current=linkedFixture(),incoming=linkedFixture();current.setups[1].expandedGroupIds=['vehicles'];incoming.setups[0].expandedGroupIds=['vehicles'];const before=JSON.stringify([current,incoming]),merged=C.merge(current,incoming),parent=merged.lists[3].id;assert.deepEqual(plain(merged.setups.map(a=>a.expandedGroupIds)),[[],['vehicles'],[parent],[]]);assert.notEqual(parent,'vehicles');assert.equal(JSON.stringify([current,incoming]),before);assert.deepEqual(plain(C.parseBackup(JSON.stringify(merged))),plain(merged));
});
