test('list deletion requires an explicit all-profile confirmation, Cancel preserves drafts, and Undo restores global data',()=>{
 const s=linkedFixture();C.setHiddenLists(s,s.setups[1],['vehicles']);const app=ui(s);try{const before=app.saved();app.d.querySelector('[aria-label="Edit Car models"]').click();app.input('list-name','Unsaved draft');app.get('list-delete').click();assert.equal(app.get('delete-list-dialog').open,true);assert.match(app.get('delete-list-warning').textContent,/Car models.*all 2 profiles/);assert.match(app.get('delete-list-dialog').textContent,/shared library and every profile/);assert.equal(app.get('delete-list-confirm').textContent,'Delete from all profiles');assert.equal(app.d.activeElement.id,'delete-list-cancel');assert.deepEqual(app.saved(),before);app.get('delete-list-cancel').click();assert.equal(app.get('list-dialog').open,true);assert.equal(app.get('list-name').value,'Unsaved draft');assert.deepEqual(app.saved(),before);app.get('list-delete').click();app.get('delete-list-dialog').dispatchEvent(new app.w.Event('cancel',{cancelable:true}));assert.equal(app.get('delete-list-dialog').open,false);assert.deepEqual(app.saved(),before);app.get('list-delete').click();app.get('delete-list-confirm').click();assert.ok(!app.saved().lists.some(l=>l.id==='car_models'));assert.ok(app.saved().lists[0].links.every(l=>l.listId!=='car_models'));assert.equal(app.get('delete-list-dialog').open,false);assert.equal(app.get('list-dialog').open,false);app.get('undo').click();assert.deepEqual(app.saved(),before);}finally{app.dom.window.close();}
});
test('show-hide drafts are cancelable, save immediately per profile, and preserve hidden positions and saved results',()=>{
 const s=make(),a=s.setups[0];C.recordResult(s,a,C.generate(s,a,()=>0));C.toggleLock(s,a,a.lastResult.picks[0]);C.toggleFavorite(s,a.lastResult,a.name);const app=ui(s);try{const before=app.saved();app.get('manage-visibility').click();assert.match(app.get('visibility-profile').textContent,/First/);app.change('show-cars',false);assert.deepEqual(app.saved(),before);app.get('visibility-cancel').click();assert.deepEqual(app.saved(),before);app.get('manage-visibility').click();assert.equal(app.get('show-cars').checked,true);app.change('show-cars',false);app.get('visibility-apply').click();const saved=JSON.parse(app.w.localStorage.getItem(C.STORAGE_KEY));assert.deepEqual(displayedLists(app),['cities','places']);assert.deepEqual(saved.setups[0].hiddenListIds,['cars']);assert.deepEqual(saved.setups[0].listIds,['cities']);assert.deepEqual(saved.setups[0].lockedPicks,[]);assert.deepEqual(saved.setups[0].listOrder,before.setups[0].listOrder);assert.deepEqual(saved.setups[1],before.setups[1]);assert.deepEqual(saved.setups[0].lastResult,before.setups[0].lastResult);assert.deepEqual(saved.favorites,before.favorites);assert.deepEqual(saved.lists,before.lists);app.d.querySelectorAll('#setup-nav button')[1].click();assert.ok(displayedLists(app).includes('cars'));app.d.querySelectorAll('#setup-nav button')[0].click();assert.ok(!displayedLists(app).includes('cars'));const reloaded=ui(app.saved());try{assert.ok(!displayedLists(reloaded).includes('cars'));reloaded.get('manage-visibility').click();reloaded.get('visibility-show-all').click();reloaded.get('visibility-apply').click();assert.deepEqual(displayedLists(reloaded),before.setups[0].listOrder);assert.equal(reloaded.get('check-cars').checked,false);}finally{reloaded.dom.window.close();}}finally{app.dom.window.close();}
});
test('hidden lists stay out of search, Select all and reordering while the visibility manager can find and restore them',()=>{
 const app=ui(make());try{const original=app.saved().setups[0].listOrder;app.get('manage-visibility').click();app.change('show-cars',false);app.get('visibility-apply').click();app.input('list-search','Cars');assert.deepEqual(displayedLists(app),[]);app.get('select-all').click();assert.ok(!app.saved().setups[0].listIds.includes('cars'));app.input('list-search','');key(app,'drag-places','Home');assert.deepEqual(app.saved().setups[0].listOrder,['cars','places','cities']);assert.equal(app.saved().setups[0].listOrder.indexOf('cars'),original.indexOf('cars'));app.get('manage-visibility').click();app.input('visibility-search','Cars');assert.equal(app.get('visibility-rows').querySelectorAll('label').length,1);assert.equal(app.get('show-cars').checked,false);app.change('show-cars',true);app.get('visibility-apply').click();assert.deepEqual(displayedLists(app),['cars','places','cities']);assert.equal(app.get('check-cars').checked,false);}finally{app.dom.window.close();}
});
