test('hidden-profile backups export and restore by replace or merge with correct visibility and no global loss',async()=>{
 const s=linkedFixture();C.setHiddenLists(s,s.setups[0],['vehicles']);s.setups[0].expandedGroupIds=['vehicles'];const app=ui(s);try{let blob;app.w.URL.createObjectURL=b=>{blob=b;return 'blob:backup';};app.w.URL.revokeObjectURL=()=>{};app.w.HTMLAnchorElement.prototype.click=()=>{};app.get('export-backup').click();const text=await new Promise(resolve=>{const r=new app.w.FileReader();r.onload=()=>resolve(r.result);r.readAsText(blob);});const backup=JSON.parse(text);assert.equal(backup.version,13);assert.deepEqual(backup.setups[0].hiddenListIds,['vehicles']);assert.deepEqual(backup.setups[1].hiddenListIds,[]);
  for(const mode of ['merge','replace']){Object.defineProperty(app.get('backup-file'),'files',{configurable:true,value:[{name:'visibility.json',size:text.length,text:async()=>text}]});await app.get('backup-file').onchange();app.d.querySelector(`input[name="backup-mode"][value="${mode}"]`).checked=true;app.get('backup-apply').click();const saved=app.saved(),setup=saved.setups.find(a=>a.id===saved.activeSetupId),parent=saved.lists.find(l=>l.id===setup.hiddenListIds[0]);assert.ok(parent.links.length);assert.deepEqual(setup.expandedGroupIds,[parent.id]);assert.ok(!displayedLists(app).includes(parent.id));assert.equal(app.saved().lists.length,mode==='merge'?6:3);assert.ok(C.validate(saved));}
 }finally{app.dom.window.close();}
});
