 app.get('output-vehicles').click();app.change('output-hide-category',true);app.input('output-before','He drives an old');app.input('output-after','that is rusty.');app.get('output-apply').click();const saved=app.saved();assert.equal(saved.setups[0].lastResult.text,'He drives an old BMW M3 that is rusty.');assert.deepEqual(saved.setups[0].lastResult.picks,before.setups[0].lastResult.picks);assert.equal(saved.setups[0].lastResult.createdAt,before.setups[0].lastResult.createdAt);assert.deepEqual(saved.setups[0].lockedPicks,before.setups[0].lockedPicks);assert.deepEqual(saved.setups[1],before.setups[1]);assert.deepEqual(saved.recentResults,before.recentResults);assert.deepEqual(saved.favorites,before.favorites);assert.equal(app.d.activeElement.id,'output-vehicles');assert.match(app.get('output-vehicles').textContent,/•/);assert.equal(app.get('lock-vehicles').getAttribute('aria-pressed'),'true');assert.match(app.get('lock-vehicles').textContent,/Car, BMW M3/);app.change('include-list-names',true);assert.equal(app.get('result').textContent,'Vehicles: He drives an old BMW M3 that is rusty.');
