test('separator control applies immediately, respects labels, survives reload and remains separate between profiles',()=>{
 const s=make(),a=s.setups[0];a.instructions='';C.recordResult(s,a,C.generate(s,a,()=>0));C.toggleLock(s,a,a.lastResult.picks[0]);C.toggleFavorite(s,a.lastResult,a.name);const app=ui(s);try{const before=app.saved();assert.equal(app.get('output-separator').value,'commas');app.change('output-separator','spaces');assert.equal(app.get('result').textContent,'Car A Tokyo');assert.equal(JSON.parse(app.w.localStorage.getItem(C.STORAGE_KEY)).setups[0].outputSeparator,'spaces');app.change('include-list-names',true);assert.equal(app.get('result').textContent,'Cars: Car A Cities: Tokyo');app.change('output-separator','lines');assert.equal(app.get('result').textContent,'Cars: Car A\nCities: Tokyo');app.change('include-list-names',false);assert.equal(app.get('result').textContent,'Car A\nTokyo');const saved=app.saved();assert.deepEqual(saved.setups[0].lastResult.picks,before.setups[0].lastResult.picks);assert.equal(saved.setups[0].lastResult.createdAt,before.setups[0].lastResult.createdAt);assert.deepEqual(saved.setups[0].lockedPicks,before.setups[0].lockedPicks);assert.deepEqual(saved.favorites,before.favorites);assert.deepEqual(saved.recentResults,before.recentResults);app.d.querySelectorAll('#setup-nav button')[1].click();assert.equal(app.get('output-separator').value,'commas');app.d.querySelectorAll('#setup-nav button')[0].click();assert.equal(app.get('output-separator').value,'lines');const reload=ui(app.saved());try{assert.equal(reload.get('output-separator').value,'lines');assert.equal(reload.get('result').textContent,'Car A\nTokyo');}finally{reload.dom.window.close();}
 }finally{app.dom.window.close();}
});
test('editing a child updates a parent-only result and both previews without selecting the child or changing locks',()=>{
 const s=linkedFixture(),a=s.setups[0];a.outputSeparator='spaces';a.expandedGroupIds=['vehicles'];C.setOutputOptions(s,a,'vehicles',{hideCategory:true,before:'At sunset,',after:'by the road.'});C.recordResult(s,a,C.generate(s,a,seededPicks(0,2)));C.toggleLock(s,a,a.lastResult.picks[0]);C.toggleFavorite(s,a.lastResult,a.name);const app=ui(s);try{const before=app.saved();assert.equal(app.get('check-car_models').checked,false);app.get('output-car_models').click();app.input('output-before','he drives an old');app.input('output-after','that is rusty');assert.equal(app.get('output-parent-preview').hidden,false);assert.equal(app.get('output-parent-name').textContent,'Through Vehicles');assert.equal(app.get('output-parent-text').textContent,'At sunset, he drives an old Honda Civic that is rusty by the road.');assert.equal(app.get('result').textContent,before.setups[0].lastResult.text);app.get('output-apply').click();assert.equal(app.get('result').textContent,'At sunset, he drives an old Honda Civic that is rusty by the road.');assert.equal(app.get('check-car_models').checked,false);const saved=app.saved();assert.deepEqual(saved.setups[0].listIds,['vehicles']);assert.deepEqual(saved.setups[0].lockedPicks,before.setups[0].lockedPicks);assert.deepEqual(saved.setups[0].lastResult.picks,before.setups[0].lastResult.picks);assert.deepEqual(saved.recentResults,before.recentResults);assert.deepEqual(saved.favorites,before.favorites);assert.deepEqual(saved.setups[1],before.setups[1]);app.get('output-vehicles').click();assert.equal(app.get('output-preview').textContent,app.get('result').textContent);app.get('output-cancel').click();app.get('undo').click();assert.deepEqual(app.saved(),before);
 }finally{app.dom.window.close();}
});
test('child draft previews use a linked parent when unchecked, remain literal, and cancel without changes',()=>{
 const s=linkedFixture();s.setups[0].expandedGroupIds=['vehicles'];s.setups[0].listIds=[];C.setOutputOptions(s,s.setups[0],'vehicles',{hideCategory:true,before:'Before',after:'after.'});let calls=0;const app=ui(s,w=>{w.crypto.getRandomValues=array=>{calls++;array.fill(0);return array;};});try{const before=app.saved();app.get('output-car_models').click();app.input('output-before','<img src=x>');assert.equal(app.get('output-parent-text').textContent,'Before <img src=x> BMW M3 after.');assert.equal(app.get('output-parent-text').querySelector('img'),null);assert.equal(calls,0);app.get('output-cancel').click();assert.deepEqual(app.saved(),before);
 }finally{app.dom.window.close();}
});
test('separator choices copy with duplicated profiles, default for new ones, and old named profiles migrate to new lines',()=>{
 const s=make();s.setups[0].outputSeparator='spaces';const app=ui(s);try{app.get('duplicate-setup').click();app.input('setup-name','Copied');app.get('setup-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(app.get('output-separator').value,'spaces');app.get('new-setup').click();app.input('setup-name','New');app.get('setup-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(app.get('output-separator').value,'commas');}finally{app.dom.window.close();}
 const old=make();old.version=11;old.setups[0].includeListNames=true;old.setups.forEach(a=>delete a.outputSeparator);const legacy=ui(old);try{assert.equal(legacy.get('output-separator').value,'lines');legacy.change('include-list-names',false);assert.equal(legacy.get('output-separator').value,'lines');}finally{legacy.dom.window.close();}
});
test('backup export and both restore paths preserve separators and automatic child formatting',async()=>{
 const s=linkedFixture();s.setups[0].outputSeparator='spaces';s.setups[1].outputSeparator='lines';C.setOutputOptions(s,s.setups[0],'vehicles',{hideCategory:true,before:'',after:''});C.setOutputOptions(s,s.setups[0],'car_models',{hideCategory:false,before:'He drives',after:'with rust.'});const app=ui(s);try{let blob;app.w.URL.createObjectURL=b=>{blob=b;return 'blob:backup';};app.w.URL.revokeObjectURL=()=>{};app.w.HTMLAnchorElement.prototype.click=()=>{};app.get('export-backup').click();const text=await new Promise(resolve=>{const r=new app.w.FileReader();r.onload=()=>resolve(r.result);r.readAsText(blob);});const backup=JSON.parse(text);assert.equal(backup.version,13);assert.deepEqual(backup.setups.map(a=>a.outputSeparator),['spaces','lines']);
 for(const mode of ['merge','replace']){const restored=ui(make());try{Object.defineProperty(restored.get('backup-file'),'files',{value:[{name:'separators.json',size:text.length,text:async()=>text}],configurable:true});await restored.get('backup-file').onchange();restored.d.querySelector(`input[name="backup-mode"][value="${mode}"]`).checked=true;restored.get('backup-apply').click();assert.equal(restored.get('output-separator').value,'spaces');const saved=restored.saved(),a=saved.setups.find(a=>a.id===saved.activeSetupId);assert.equal(C.generate(saved,a,()=>0).text,'He drives BMW M3 with rust.');assert.equal(a.listIds.length,1);}finally{restored.dom.window.close();}}
 }finally{app.dom.window.close();}
});

test('output text can be disabled across parent, automatic child and separate multi-pick draws without clearing wording',()=>{
 const s=linkedFixture(),a=s.setups[0];a.instructions='Keep this instruction.';a.instructionsPosition='beginning';
 C.setOutputOptions(s,a,'vehicles',{hideCategory:true,before:'Before parent',after:'after parent.'});
 C.setOutputOptions(s,a,'car_models',{hideCategory:false,before:'Before child',after:'after child.'});
 const picks=[{listId:'vehicles',name:'Vehicles',value:'Car',child:{listId:'car_models',name:'Car models',value:'BMW M3'}},{listId:'car_models',name:'Car models',value:'Porsche 911'},{listId:'car_models',name:'Car models',value:'Honda Civic'}],options=plain(a.listOutput);
 for(const [mode,join] of [['commas',', '],['spaces',' '],['lines','\n']])for(const names of [false,true]){
  a.outputSeparator=mode;a.includeListNames=names;a.includeOutputText=true;const enabled=C.formatOutput(s,a,picks);
  a.includeOutputText=false;const label=name=>names?name+': ':'';
  assert.equal(C.formatOutput(s,a,picks),'Keep this instruction.\n\n'+[label('Vehicles')+'BMW M3',label('Car models')+'Porsche 911',label('Car models')+'Honda Civic'].join(join));
  assert.deepEqual(plain(a.listOutput),options);a.includeOutputText=true;assert.equal(C.formatOutput(s,a,picks),enabled);
 }
 a.includeOutputText=false;a.includeListNames=false;a.outputSeparator='commas';a.listOutput[0].hideCategory=false;assert.equal(C.formatPicks(a,picks),'Car, BMW M3, Porsche 911, Honda Civic');
});
test('output text choice roundtrips and merges per profile while schemas 1–12 migrate with text on',()=>{
 const s=linkedFixture();s.setups[0].includeOutputText=false;C.setOutputOptions(s,s.setups[0],'car_models',{hideCategory:false,before:'Old',after:'with rust.'});
 const round=C.parseBackup(JSON.stringify(s));assert.deepEqual(plain(round),plain(s));const merged=C.merge(make(),round);assert.deepEqual(plain(merged.setups.map(a=>a.includeOutputText)),[true,true,false,true]);assert.equal(merged.setups[2].listOutput[0].listId,merged.lists[4].id);
 for(let version=1;version<=12;version++){const old=make();old.version=version;for(const a of old.setups){delete a.includeOutputText;a.lastResult={text:'Exact saved wording.',createdAt:'2026-11-09T12:00:00Z',picks:[]};}const before=JSON.stringify(old),m=C.parseBackup(before);assert.ok(m.setups.every(a=>a.includeOutputText===true));assert.ok(m.setups.every(a=>a.lastResult.text==='Exact saved wording.'));assert.equal(JSON.stringify(old),before);}
 const old=plain(s);old.version=12;old.setups.forEach(a=>delete a.includeOutputText);const m=C.validate(old);assert.deepEqual(plain(m.setups[0].listOutput),plain(s.setups[0].listOutput));assert.equal(m.setups[0].includeOutputText,true);
 assert.equal(C.blankSetup().includeOutputText,true);
});
test('output text backups reject malformed choices and unsupported future schemas without mutation',()=>{
 for(const invalid of [undefined,null,'true','false',0,1,{},[]]){const s=make();s.setups[0].includeOutputText=invalid;const text=JSON.stringify(s);assert.throws(()=>C.parseBackup(text));assert.equal(JSON.stringify(s),text);}
 const future=make();future.version=C.VERSION+1;assert.throws(()=>C.validate(future));
});

test('output text toggle saves immediately and reformats without rerolling or changing locks, history, favorites or other profiles',()=>{
 const s=linkedFixture(),a=s.setups[0];a.expandedGroupIds=['vehicles'];C.setOutputOptions(s,a,'vehicles',{hideCategory:true,before:'He drives',after:'.'});C.setOutputOptions(s,a,'car_models',{hideCategory:false,before:'an old',after:'with rust'});C.recordResult(s,a,C.generate(s,a,()=>0));C.toggleLock(s,a,a.lastResult.picks[0]);C.toggleFavorite(s,a.lastResult,a.name);
 let calls=0;const app=ui(s,w=>{w.crypto.getRandomValues=array=>{calls++;array.fill(0);return array;};});try{
  const before=app.saved(),start=calls;assert.equal(app.get('include-output-text').checked,true);assert.equal(app.get('result').textContent,'He drives an old BMW M3 with rust.');app.change('include-output-text',false);
  const immediate=JSON.parse(app.w.localStorage.getItem(C.STORAGE_KEY));assert.equal(immediate.setups[0].includeOutputText,false);assert.equal(app.get('result').textContent,'BMW M3');assert.equal(calls,start);assert.deepEqual(immediate.setups[0].listOutput,before.setups[0].listOutput);assert.deepEqual(immediate.setups[0].lastResult.picks,before.setups[0].lastResult.picks);assert.equal(immediate.setups[0].lastResult.createdAt,before.setups[0].lastResult.createdAt);assert.deepEqual(immediate.setups[0].lockedPicks,before.setups[0].lockedPicks);assert.deepEqual(immediate.setups[1],before.setups[1]);assert.deepEqual(immediate.recentResults,before.recentResults);assert.deepEqual(immediate.favorites,before.favorites);
  const reload=ui(immediate);try{assert.equal(reload.get('include-output-text').checked,false);assert.equal(reload.get('result').textContent,'BMW M3');reload.get('generate').click();assert.equal(reload.get('result').textContent,'BMW M3');reload.get('output-car_models').click();assert.equal(reload.get('output-before').value,'an old');assert.equal(reload.get('output-preview').textContent,'BMW M3');assert.equal(reload.get('output-parent-text').textContent,'BMW M3');assert.match(reload.get('output-preview-note').textContent,/Output text is off/);reload.input('output-before','a classic');reload.get('output-apply').click();assert.equal(reload.get('result').textContent,'BMW M3');reload.change('include-output-text',true);assert.equal(reload.get('result').textContent,'He drives a classic BMW M3 with rust.');}finally{reload.dom.window.close();}
  app.change('include-output-text',true);assert.equal(app.get('result').textContent,before.setups[0].lastResult.text);assert.equal(calls,start);
 }finally{app.dom.window.close();}
});
test('output text choices stay separate between profiles, copy on duplication and default on for new profiles',()=>{
 const app=ui(linkedFixture());try{app.change('include-output-text',false);app.d.querySelectorAll('#setup-nav button')[1].click();assert.equal(app.get('include-output-text').checked,true);app.d.querySelectorAll('#setup-nav button')[0].click();assert.equal(app.get('include-output-text').checked,false);app.get('duplicate-setup').click();app.input('setup-name','Copied');app.get('setup-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(app.get('include-output-text').checked,false);assert.equal(app.saved().setups[2].includeOutputText,false);app.get('new-setup').click();app.input('setup-name','Fresh');app.get('setup-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(app.get('include-output-text').checked,true);assert.equal(app.saved().setups[3].includeOutputText,true);}finally{app.dom.window.close();}
});
test('export and replace or merge restore the disabled output text choice and its saved wording',async()=>{
 const s=linkedFixture();s.setups[0].includeOutputText=false;C.setOutputOptions(s,s.setups[0],'vehicles',{hideCategory:true,before:'He drives',after:'.'});C.setOutputOptions(s,s.setups[0],'car_models',{hideCategory:false,before:'an old',after:''});const app=ui(s);try{
  let blob;app.w.URL.createObjectURL=b=>{blob=b;return 'blob:backup';};app.w.URL.revokeObjectURL=()=>{};app.w.HTMLAnchorElement.prototype.click=()=>{};app.get('export-backup').click();const text=await new Promise(resolve=>{const r=new app.w.FileReader();r.onload=()=>resolve(r.result);r.readAsText(blob);});const backup=JSON.parse(text);assert.equal(backup.version,13);assert.deepEqual(backup.setups.map(a=>a.includeOutputText),[false,true]);assert.deepEqual(backup.setups[0].listOutput,plain(s.setups[0].listOutput));
  for(const mode of ['merge','replace']){const restored=ui(make());try{Object.defineProperty(restored.get('backup-file'),'files',{value:[{name:'output-text.json',size:text.length,text:async()=>text}],configurable:true});await restored.get('backup-file').onchange();restored.d.querySelector(`input[name="backup-mode"][value="${mode}"]`).checked=true;restored.get('backup-apply').click();assert.equal(restored.get('include-output-text').checked,false);const state=restored.saved(),a=state.setups.find(x=>x.id===state.activeSetupId);assert.equal(C.generate(state,a,()=>0).text,'BMW M3');a.includeOutputText=true;assert.equal(C.generate(state,a,()=>0).text,'He drives an old BMW M3.');}finally{restored.dom.window.close();}}
 }finally{app.dom.window.close();}
});
